59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	    }
81	
82	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
83	    @Override
84	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
85	        Collection<Owner> owners;
86	        if (lastName != null) {
87	            owners = this.clinicService.findOwnerByLastName(lastName);
88	        } else {
89	            owners = this.clinicService.findAllOwners();
90	        }
91	        if (owners.isEmpty()) {
92	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
93	        }
94	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
100	        Owner owner = this.clinicService.findOwnerById(ownerId);
101	        if (owner == null) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
110	        String address = normalizeAddress(ownerFieldsDto.getAddress());
111	        List<String> missingFields = new ArrayList<>();
112	        if (isBlank(ownerFieldsDto.getFirstName())) {
113	            missingFields.add("firstName");
114	        }
115	        if (isBlank(ownerFieldsDto.getLastName())) {
116	            missingFields.add("lastName");
117	        }
118	        if (isBlank(address)) {
119	            missingFields.add("address");
120	        }
121	        if (isBlank(ownerFieldsDto.getCity())) {
122	            missingFields.add("city");
123	        }
124	        if (isBlank(ownerFieldsDto.getTelephone())) {
125	            missingFields.add("telephone");
126	        }
127	        if (!missingFields.isEmpty()) {
128	            throw new MissingOwnerFieldsException(missingFields);
129	        }
130	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
131	        if (isTelephoneInUse(telephone)) {
132	            throw new DuplicateTelephoneException(ownerFieldsDto.getTelephone());
133	        }
134	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
135	        if (!sharesHousehold
136	            && isHouseholdInUse(ownerFieldsDto.getLastName(), address)) {
137	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), address);
138	        }
139	        if (isCityAtCapacity(ownerFieldsDto.getCity())) {
140	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
141	        }
142	        LocalDate today = LocalDate.now();
143	        if (isDailyRegistrationLimitReached(today)) {
144	            throw new DailyRegistrationLimitException(today);
145	        }
146	        HttpHeaders headers = new HttpHeaders();
147	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
148	        owner.setAddress(address);
149	        owner.setTelephone(telephone);
150	        if (owner.getRegistrationDate() == null) {
151	            owner.setRegistrationDate(LocalDate.now());
152	        }
153	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
154	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
155	        if (sharesHousehold) {
156	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
157	        }
158	        this.clinicService.saveOwner(owner);
159	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
160	        headers.setLocation(UriComponentsBuilder.newInstance()
161	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
162	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
168	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
169	        if (currentOwner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        currentOwner.setAddress(ownerFieldsDto.getAddress());
173	        currentOwner.setCity(ownerFieldsDto.getCity());
174	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
175	        currentOwner.setLastName(ownerFieldsDto.getLastName());
176	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
177	        this.clinicService.saveOwner(currentOwner);
178	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Transactional
183	    @Override
184	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
185	        Owner owner = this.clinicService.findOwnerById(ownerId);
186	        if (owner == null) {
187	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	        }
189	        this.clinicService.deleteOwner(owner);
190	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
196	        Owner owner = this.clinicService.findOwnerById(ownerId);
197	        if (owner == null) {
198	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	        }
200	        HttpHeaders headers = new HttpHeaders();
201	        Pet pet = petMapper.toPet(petFieldsDto);
202	        owner.setId(ownerId);
203	        pet.setOwner(owner);
204	        pet.getType().setName(null);
205	        this.clinicService.savePet(pet);
206	        PetDto petDto = petMapper.toPetDto(pet);
207	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
208	            .buildAndExpand(pet.getId()).toUri());
209	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
215	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
216	        if (currentOwner != null) {
217	            Pet currentPet = this.clinicService.findPetById(petId);
218	            if (currentPet != null) {
219	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
220	                currentPet.setName(petFieldsDto.getName());
221	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
222	                this.clinicService.savePet(currentPet);
223	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
224	            }
225	        }
226	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	    }
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
232	        HttpHeaders headers = new HttpHeaders();
233	        Visit visit = visitMapper.toVisit(visitFieldsDto);
234	        Pet pet = new Pet();
235	        pet.setId(petId);
236	        visit.setPet(pet);
237	        this.clinicService.saveVisit(visit);
238	        VisitDto visitDto = visitMapper.toVisitDto(visit);
239	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
240	            .buildAndExpand(visit.getId()).toUri());
241	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
242	    }
243	
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner != null) {
250	            Pet pet = owner.getPet(petId);
251	            if (pet != null) {
252	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
253	            }
254	        }
255	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
256	    }
257	
258	    private static boolean isBlank(String value) {
259	        return value == null || value.isBlank();
260	    }
261	
262	    /**
263	     * Normalizes a street address into the canonical form stored on and returned for a newly
264	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
265	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
266	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
267	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
268	     * value is what gets persisted, echoed back, and used for every address comparison (household
269	     * duplicate detection and the shared household identifier).
270	     *
271	     * @param rawAddress the address value as supplied by the client
272	     * @return the normalized address (possibly empty, never {@code null})
273	     */
274	    private static String normalizeAddress(String rawAddress) {
275	        if (rawAddress == null) {
276	            return "";
277	        }
278	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
279	        if (collapsed.isEmpty()) {
280	            return "";
281	        }
282	        String[] tokens = collapsed.split(" ");
283	        StringBuilder sb = new StringBuilder(collapsed.length());
284	        for (int i = 0; i < tokens.length; i++) {
285	            String token = tokens[i];
286	            switch (token) {
287	                case "ST" -> token = "STREET";
288	                case "RD" -> token = "ROAD";
289	                case "AVE" -> token = "AVENUE";
290	                default -> { }
291	            }
292	            if (i > 0) {
293	                sb.append(' ');
294	            }
295	            sb.append(token);
296	        }
297	        return sb.toString();
298	    }
299	
300	    /**
301	     * Builds the customer code assigned to a newly created owner. The code is formatted
302	     * {@code <CITY3>-<LAST3>-<NNNN>} where {@code CITY3} is the upper-cased first three letters
303	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's
304	     * last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more
305	     * than the number of owners already in that city (e.g. {@code LON-SMI-0007}).
306	     *
307	     * @param city the city of the owner being created
308	     * @param lastName the last name of the owner being created
309	     * @return the customer code to assign
310	     */
311	    private String nextCustomerCode(String city, String lastName) {
312	        String city3 = letterPrefix3(city);
313	        String last3 = letterPrefix3(lastName);
314	        String normalizedCity = normalizeIdentity(city);
315	        long sequence = this.clinicService.findAllOwners().stream()
316	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
317	            .count() + 1L;
318	        return String.format("%s-%s-%04d", city3, last3, sequence);
319	    }
320	
321	    /**
322	     * Returns the upper-cased first three letters of the given value, skipping any non-letter
323	     * characters. Values with fewer than three letters yield a shorter prefix.
324	     *
325	     * @param value the source text
326	     * @return the upper-cased letter prefix (at most three characters, never {@code null})
327	     */
328	    private static String letterPrefix3(String value) {
329	        StringBuilder prefix = new StringBuilder(3);
330	        if (value != null) {
331	            for (int i = 0; i < value.length() && prefix.length() < 3; i++) {
332	                char c = value.charAt(i);
333	                if (Character.isLetter(c)) {
334	                    prefix.append(Character.toUpperCase(c));
335	                }
336	            }
337	        }
338	        return prefix.toString();
339	    }
340	
341	    /**
342	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
343	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
344	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
345	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits.
346	     *
347	     * @param rawTelephone the telephone value as supplied by the client
348	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
349	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
350	     */
351	    private static String normalizeTelephone(String rawTelephone) {
352	        if (rawTelephone == null) {
353	            throw new InvalidTelephoneException(rawTelephone);
354	        }
355	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
356	        String e164;
357	        if (cleaned.startsWith("+")) {
358	            String digits = cleaned.substring(1);
359	            if (!digits.matches("[0-9]+")) {
360	                throw new InvalidTelephoneException(rawTelephone);
361	            }
362	            e164 = "+" + digits;
363	        } else {
364	            if (!cleaned.matches("[0-9]+")) {
365	                throw new InvalidTelephoneException(rawTelephone);
366	            }
367	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
368	            e164 = "+61" + national;
369	        }
370	        int digitCount = e164.length() - 1;
371	        if (digitCount < 8 || digitCount > 15) {
372	            throw new InvalidTelephoneException(rawTelephone);
373	        }
374	        return e164;
375	    }
376	
377	    /**
378	     * Determines whether any existing owner already uses the given E.164 telephone. Stored
379	     * telephones are themselves E.164, so the values are compared directly.
380	     *
381	     * @param e164Telephone the E.164 telephone of the owner being created
382	     * @return {@code true} if another owner already has the same E.164 telephone
383	     */
384	    private boolean isTelephoneInUse(String e164Telephone) {
385	        return this.clinicService.findAllOwners().stream()
386	            .map(Owner::getTelephone)
387	            .filter(existing -> existing != null)
388	            .anyMatch(e164Telephone::equals);
389	    }
390	
391	    /**
392	     * Determines whether any existing owner already shares a household with the owner being created,
393	     * i.e. has both the same last name and the same address. Both fields are compared
394	     * case-insensitively after collapsing runs of whitespace to a single space and trimming.
395	     *
396	     * @param lastName the last name of the owner being created
397	     * @param address the address of the owner being created
398	     * @return {@code true} if another owner already has the same last name and address
399	     */
400	    private boolean isHouseholdInUse(String lastName, String address) {
401	        String normalizedLastName = normalizeIdentity(lastName);
402	        String normalizedAddress = normalizeIdentity(address);
403	        return this.clinicService.findAllOwners().stream()
404	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
405	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress));
406	    }
407	
408	    /**
409	     * Counts how many existing owners already share the given first name and last name with the
410	     * owner being created. Both names are compared case-insensitively (after trimming and
411	     * collapsing runs of whitespace). The count reflects the state before the new owner is
412	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
413	     *
414	     * @param firstName the first name of the owner being created
415	     * @param lastName the last name of the owner being created
416	     * @return the number of existing owners sharing the same first and last name
417	     */
418	    private int namesakeCount(String firstName, String lastName) {
419	        String normalizedFirstName = normalizeIdentity(firstName);
420	        String normalizedLastName = normalizeIdentity(lastName);
421	        return (int) this.clinicService.findAllOwners().stream()
422	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
423	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
424	            .count();
425	    }
426	
427	    /**
428	     * The maximum number of owners permitted in a single city. Once a city already contains this
429	     * many owners it is considered full and no further owners may be created there.
430	     */
431	    private static final int CITY_CAPACITY = 50;
432	
433	    /**
434	     * Determines whether the given city has already reached its capacity, i.e. already contains
435	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
436	     * collapsing runs of whitespace to a single space and trimming.
437	     *
438	     * @param city the city of the owner being created
439	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
440	     */
441	    private boolean isCityAtCapacity(String city) {
442	        String normalizedCity = normalizeIdentity(city);
443	        long count = this.clinicService.findAllOwners().stream()
444	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
445	            .count();
446	        return count >= CITY_CAPACITY;
447	    }
448	
449	    /**
450	     * The maximum number of owners that may be created on any single day. Once this many owners
451	     * already carry a {@code registrationDate} of the current day, no further owners may be created
452	     * that day.
453	     */
454	    private static final int DAILY_REGISTRATION_LIMIT = 100;
455	
456	    /**
457	     * Determines whether the daily registration limit has already been reached, i.e. whether
458	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
459	     * their {@code registrationDate}.
460	     *
461	     * @param date the current day
462	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
463	     *         registered on the given date
464	     */
465	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
466	        long count = this.clinicService.findAllOwners().stream()
467	            .filter(existing -> date.equals(existing.getRegistrationDate()))
468	            .count();
469	        return count >= DAILY_REGISTRATION_LIMIT;
470	    }
471	
472	    /**
473	     * Assigns the owner being created to the household identified by the given last name and
474	     * address and returns the household's stable shared identifier. The identifier is derived
475	     * deterministically from the normalized last name and address, so every member of the same
476	     * household resolves to the same value regardless of creation order. Any existing member that
477	     * does not yet carry the identifier is back-filled so all household members share it.
478	     *
479	     * @param lastName the last name of the owner being created
480	     * @param address the address of the owner being created
481	     * @return the stable household identifier shared by all members of the household
482	     */
483	    private String joinHousehold(String lastName, String address) {
484	        String householdId = householdIdFor(lastName, address);
485	        String normalizedLastName = normalizeIdentity(lastName);
486	        String normalizedAddress = normalizeIdentity(address);
487	        for (Owner existing : this.clinicService.findAllOwners()) {
488	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
489	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
490	                && !householdId.equals(existing.getHouseholdId())) {
491	                existing.setHouseholdId(householdId);
492	                this.clinicService.saveOwner(existing);
493	            }
494	        }
495	        return householdId;
496	    }
497	
498	    /**
499	     * Derives the stable household identifier for a given last name and address. The value is the
500	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
501	     * address, so it is stable across calls and identical for every member of the household.
502	     *
503	     * @param lastName the last name of the household
504	     * @param address the address of the household
505	     * @return the stable household identifier
506	     */
507	    private static String householdIdFor(String lastName, String address) {
508	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
509	        try {
510	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
511	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
512	            StringBuilder sb = new StringBuilder(digest.length * 2);
513	            for (byte b : digest) {
514	                sb.append(String.format("%02x", b));
515	            }
516	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
517	        }
518	        catch (java.security.NoSuchAlgorithmException e) {
519	            throw new IllegalStateException("SHA-256 not available", e);
520	        }
521	    }
522	
523	    /**
524	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
525	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
526	     * single space, and the result is lower-cased.
527	     *
528	     * @param value the raw field value
529	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
530	     */
531	    private static String normalizeIdentity(String value) {
532	        if (value == null) {
533	            return "";
534	        }
535	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
536	    }
537	}
