95	    public String getEmail() {
96	        return this.email;
97	    }
98	
99	    /**
100	     * Stores the email lower-cased so it is persisted and returned in a canonical form. A
101	     * {@code null} value (email omitted) is preserved as {@code null}.
102	     */
103	    public void setEmail(String email) {
104	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
105	    }
