120	        this.customerCode = customerCode;
121	    }
122	
123	    /**
124	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where {@code YY} is
125	     * the last two digits of the {@code registrationDate} year (e.g. {@code LON-SMI-0007-M26}).
126	     * Derived from the owner's own fields; {@code null} until both are assigned.
127	     */
128	    @Transient
129	    public String getMembershipNumber() {
130	        if (this.customerCode == null || this.registrationDate == null) {
131	            return null;
132	        }
133	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
134	    }
